#include <cstddef>
#include <initializer_list>
#include <iostream>
#include <vector>

struct SearchResult {
    std::size_t index;
    std::size_t comparisons;
};

SearchResult lower_boundary(const std::vector<int>& values, int target) {
    std::size_t low = 0;
    std::size_t high = values.size();
    std::size_t comparisons = 0;

    while (low < high) {
        const std::size_t mid = low + (high - low) / 2;
        ++comparisons; // Count only the value-to-target comparison below.
        if (values[mid] < target) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    return {low, comparisons};
}

int main() {
    const std::vector<int> values{2, 6, 6, 6, 9, 13};
    std::cout << std::boolalpha;
    for (const int target : {6, 7, 20, -1}) {
        const SearchResult result = lower_boundary(values, target);
        const bool present = result.index < values.size()
                          && values[result.index] == target;
        std::cout << target << ": boundary=" << result.index
                  << " comparisons=" << result.comparisons
                  << " present=" << present << '\n';
    }
}

