    std::size_t low = 0;
    std::size_t high = values.size();

    // Deliberately incorrect update; the step limit makes the demo finite.
    for (int step = 1; step <= 3 && low < high; ++step) {
        const std::size_t mid = low + (high - low) / 2;
        std::cout << "step " << step << ": [" << low << ',' << high
                  << ") mid=" << mid;
        if (values[mid] < target) {
            low = mid; // BUG: the already rejected element is retained.
        } else {
            high = mid;
        }
        std::cout << " next=[" << low << ',' << high << ")\n";
    }
    std::cout << "interval still nonempty: " << std::boolalpha
              << (low < high) << '\n';
}

#include <algorithm>
#include <cstddef>
#include <initializer_list>
#include <iostream>
#include <vector>

struct SearchResult {
    std::size_t index;
    std::size_t comparisons;
};

SearchResult lower_boundary(const std::vector<int>& values, int target) {
    std::size_t low = 0;
    std::size_t high = values.size();
    std::size_t comparisons = 0;

    while (low < high) {
        const std::size_t mid = low + (high - low) / 2;
        ++comparisons; // Count only the value-to-target comparison below.
        if (values[mid] < target) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    return {low, comparisons};
}

std::size_t comparison_bound(std::size_t n) {
    std::size_t count = 0;
    while (n > 0) {
        ++count;
        n /= 2;
    }
    return count;
}

int main() {
    const std::vector<std::vector<int>> cases{
        {}, {4}, {4, 4, 4, 4}, {0, 2, 4, 6, 8},
        {1, 1, 3, 3, 5, 5, 7}, {0, 1, 2, 3, 4, 5, 6, 7}
    };
    std::size_t checked = 0;
    for (const auto& values : cases) {
        std::size_t worst = 0;
        const std::size_t bound = comparison_bound(values.size());
        for (const int target : {-1, 0, 3, 4, 8, 9}) {
            const SearchResult result = lower_boundary(values, target);
            const auto expected = std::lower_bound(
                values.begin(), values.end(), target);
            const auto expected_index = static_cast<std::size_t>(
                expected - values.begin());
            if (result.index != expected_index || result.comparisons > bound) {
                std::cout << "verification failed\n";
                return 1;
            }
            worst = std::max(worst, result.comparisons);
            ++checked;
        }
        if (worst != bound) {
            std::cout << "worst-case witness missing\n";
            return 1;
        }
        std::cout << "n=" << values.size() << " worst=" << worst
                  << " bound=" << bound << '\n';
    }
    std::cout << "verified " << checked << " searches\n";
}
